INSERT INTO public.products (id, nome, sabor, categoria, preco, volume_ml, estoque, notas_aromaticas, descricao, sugestoes, foto_url, ativo, graduacao_gl, brix, pedidos_count, ordem, created_at, updated_at, ingredientes, fotos) VALUES ('03b9242c-50a5-4c7d-bb5e-0211b266b421', 'Poção do Doce Deleite', 'Doce de Leite', 'cremoso', 45, 750, 0, 'Cremoso • Caramelo • Canela', 'Licor cremoso artesanal de doce de leite com baunilha e canela. Doce e aconchegante, com textura aveludada e aroma caramelizado.', 'Dose gelada: servir como digestivo em copo pequeno. Gelar intensifica a cremosidade. Sobremesas intensas: ideal com doces de café ou chocolate amargo (ex., brigadeiro gourmet, pudim ou mousse de café). O licor adoça e complementa sabores caramelizados. Drinks cremosos: experimente em coquetéis como versão doce do Espress Martini (café + licor de doce de leite). Confere textura aveludada e aroma de caramelo. Coberturas: pode ser usado como calda sobre sorvetes, cheesecakes ou panquecas, ampliando camadas de sabor.', 'https://pldyufxqitpoyutiszhc.supabase.co/storage/v1/object/public/product-images/1782952238678-hwtqc1/card.webp', true, 12.5, 28, 1, 11, '2026-05-15T20:15:03.142933+00:00', '2026-07-02T00:31:46.543042+00:00', 'Doce de leite, Açúcar, Álcool de Cereais, Canela em pó e Essência de baunilha.', '[{"card": "https://pldyufxqitpoyutiszhc.supabase.co/storage/v1/object/public/product-images/1782952238678-hwtqc1/card.webp", "full": "https://pldyufxqitpoyutiszhc.supabase.co/storage/v1/object/public/product-images/1782952238678-hwtqc1/full.webp", "thumb": "https://pldyufxqitpoyutiszhc.supabase.co/storage/v1/object/public/product-images/1782952238678-hwtqc1/thumb.webp"}, {"card": "https://pldyufxqitpoyutiszhc.supabase.co/storage/v1/object/public/product-images/1782952243268-pf65te/card.webp", "full": "https://pldyufxqitpoyutiszhc.supabase.co/storage/v1/object/public/product-images/1782952243268-pf65te/full.webp", "thumb": "https://pldyufxqitpoyutiszhc.supabase.co/storage/v