INSERT INTO public.products (id, nome, sabor, categoria, preco, volume_ml, estoque, notas_aromaticas, descricao, sugestoes, foto_url, ativo, graduacao_gl, brix, pedidos_count, ordem, created_at, updated_at, ingredientes, fotos) VALUES ('f57e85ca-3e25-4885-a9b8-8febeac0421a', 'Poção da Conexão', 'Figo', 'fino', 35, 750, 12, 'Herbácea • Frutada Suave • Leve', 'Notas verdes e amadeiradas com doçura sutil, lembra tardes de verão. ', 'Servir gelado, puro ou com gelo. Pode ser usado em coquetéis com gin ou vodka para realçar o aroma herbal. Harmoniza com queijos frescos (cabra, ricota), frutas secas e saladas delicadas.', 'https://pldyufxqitpoyutiszhc.supabase.co/storage/v1/object/public/product-images/1782951946741-ayqcvp/card.webp', true, 21, 31, 0, 6, '2026-05-15T20:15:03.142933+00:00', '2026-07-02T00:25:47.700242+00:00', 'Açúcar, Álcool de Cereais e Folhas de figueira.', '[{"card": "https://pldyufxqitpoyutiszhc.supabase.co/storage/v1/object/public/product-images/1782951946741-ayqcvp/card.webp", "full": "https://pldyufxqitpoyutiszhc.supabase.co/storage/v1/object/public/product-images/1782951946741-ayqcvp/full.webp", "thumb": "https://pldyufxqitpoyutiszhc.supabase.co/storage/v1/object/public/product-images/1782951946741-ayqcvp/thumb.webp"}, {"card": "https://pldyufxqitpoyutiszhc.supabase.co/storage/v1/object/public/product-images/1782951952025-abmmyl/card.webp", "full": "https://pldyufxqitpoyutiszhc.supabase.co/storage/v1/object/public/product-images/1782951952025-abmmyl/full.webp", "thumb": "https://pldyufxqitpoyutiszhc.supabase.co/storage/v1/object/public/product-images/1782951952025-abmmyl/thumb.webp"}, {"card": "https://pldyufxqitpoyutiszhc.supabase.co/storage/v1/object/public/product-images/1782951956130-n4vba9/card.webp", "full": "https://pldyufxqitpoyutiszhc.supabase.co/storage/v1/object/public/product-images/1782951956130-n4vba9/full.webp", "thumb": "https://pldyufxqitpoyutiszhc.supabase.co/storage/v1/object/public/product-images/1782951956130-n4vba9/thumb.webp"